<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { listAgentLibrary, listTeamPresets, getProjectAgentNode, saveProjectAgentNodeDraft, getProjectAgentContexts, saveProjectAgentContexts, reviseProjectAgentConfiguration } from '../api/agent-library.api'
import { getCurrentWorkflowRun, startWorkflowRun } from '../api/workflow.api'
import { getWikiDocuments } from '../api/wiki.api'
import { searchDocumentAgentFeishu } from '../api/document-agent.api'
import { getSkills } from '../api/skills.api'
import { MessagePlugin } from 'tdesign-vue-next'
import type { SkillView } from '../types/skill'
import type { AgentLibraryProfile, AgentTeamBinding, AgentTeamPreset, ProjectAgentContext, ProjectAgentContexts, ProjectAgentNodeDraft } from '../types/agent-library'
import { useProjectSetupStore } from '../stores/projectSetup'

const route = useRoute(); const router = useRouter(); const setup = useProjectSetupStore(); const projectKey = String(route.params.projectKey)
const profiles = ref<AgentLibraryProfile[]>([]); const presets = ref<AgentTeamPreset[]>([]); const source = ref<'SYSTEM_PRESET'|'PROJECT_COPY'|'CUSTOM'>('SYSTEM_PRESET'); const selectedPreset = ref<string|number|null>(null); const sourceProjectKey = ref(''); const selectedDraft = ref<ProjectAgentNodeDraft|null>(null); const contexts = ref<ProjectAgentContexts>({ platformWiki: [], feishu: [] }); const initialRequest = ref(''); const wikiQuery = ref(''); const feishuQuery = ref(''); const contextTab = ref<'PLATFORM_WIKI'|'FEISHU'>('PLATFORM_WIKI'); const message = ref(''); const busy = ref(false); const saving = ref(false); const validating = ref(false); const resolvingEntry = ref(true); const skillQuery = ref(''); const skillResults = ref<SkillView[]>([]); const skillSearching = ref(false)
const selectedNode = computed(() => setup.configuration?.nodes.find(n => `${n.stageKey}/${n.nodeKey}` === setup.selectedNodeKey)); const ready = computed(() => setup.configuration?.status === 'READY'); const draftMode = computed(() => setup.configuration?.status === 'DRAFT')
const groupedNodes = computed(() => {
  const groups = new Map<string, { key: string; label: string; nodes: AgentTeamBinding[] }>()
  for (const node of setup.configuration?.nodes ?? []) {
    const key = String(node.stageKey)
    const existing = groups.get(key)
    if (existing) existing.nodes.push(node)
    else groups.set(key, { key, label: node.stageDisplayName || node.stageName || node.stageKey, nodes: [node] })
  }
  return [...groups.values()]
})
const runtimeConfigText = computed({ get: () => typeof selectedDraft.value?.runtimeConfigJson === 'string' ? selectedDraft.value.runtimeConfigJson : JSON.stringify(selectedDraft.value?.runtimeConfigJson ?? {}, null, 2), set: value => { if (selectedDraft.value) selectedDraft.value.runtimeConfigJson = value } })
async function loadNode() { if (!selectedNode.value) return; try { selectedDraft.value = await getProjectAgentNode(projectKey, selectedNode.value.stageKey, selectedNode.value.nodeKey) } catch (e) { message.value = e instanceof Error ? e.message : 'Agent 草稿加载失败' } }
function selectedSkill(skillKey: string) { return selectedDraft.value?.skills?.some(skill => skill.skillKey === skillKey) ?? false }
function addSkill(skill: SkillView) { if (!selectedDraft.value || selectedSkill(skill.skillKey)) return; const skills = selectedDraft.value.skills ?? []; selectedDraft.value.skills = [...skills, { skillId: skill.id, skillKey: skill.skillKey, name: skill.displayName, versionPolicy: 'LATEST_PUBLISHED', required: true, sortOrder: skills.length }] }
function removeSkill(skillKey: string) { if (!selectedDraft.value) return; selectedDraft.value.skills = (selectedDraft.value.skills ?? []).filter(skill => skill.skillKey !== skillKey).map((skill, index) => ({ ...skill, versionPolicy: 'LATEST_PUBLISHED', fixedSkillVersionId: undefined, required: true, sortOrder: index })) }
async function searchSkills() { skillSearching.value = true; try { const page = await getSkills({ keyword: skillQuery.value.trim() || undefined, status: 'ACTIVE', page: 0, size: 20, sort: 'skillKey,asc' }); skillResults.value = page.items.filter(skill => Boolean(skill.latestPublishedVersion) && (!skill.scopeType || skill.scopeType === 'PLATFORM')) } catch (e) { MessagePlugin.error(e instanceof Error ? e.message : 'Skill 搜索失败') } finally { skillSearching.value = false } }
const wikiResults = ref<ProjectAgentContext[]>([]); const feishuResults = ref<ProjectAgentContext[]>([])
async function loadAll() { await Promise.allSettled([setup.load(projectKey), setup.loadReusable(projectKey), listAgentLibrary().then(v => profiles.value = v), listTeamPresets().then(v => { presets.value = v; selectedPreset.value = v.find(x => x.isDefault)?.versionId ?? v[0]?.versionId ?? null }), getProjectAgentContexts(projectKey).then(v => contexts.value = v)]); const firstNode = setup.configuration?.nodes?.[0]; if (firstNode) { setup.selectedNodeKey = `${firstNode.stageKey}/${firstNode.nodeKey}`; await loadNode() } }
async function resolveEntry() { try { const run = await getCurrentWorkflowRun(projectKey); await router.replace({ name: 'project-workspace', params: { projectId: projectKey, runId: String(run.id) } }) } catch (error) { const status = (error as any)?.response?.status; const code = (error as any)?.response?.data?.code; if (status === 404 || code === 'WORKFLOW_RUN_NOT_FOUND') { resolvingEntry.value = false; await loadAll() } else { resolvingEntry.value = false; message.value = (error as any)?.response?.data?.message || '工作流状态查询失败，请稍后重试' } } }
onMounted(resolveEntry)
async function applySource() { busy.value = true; try { setup.clearValidation(); if (source.value === 'SYSTEM_PRESET' && selectedPreset.value != null) await setup.usePreset(projectKey, selectedPreset.value); else if (source.value === 'PROJECT_COPY' && sourceProjectKey.value) await setup.copyFrom(projectKey, sourceProjectKey.value); setup.selectedNodeKey = setup.configuration?.nodes[0] ? `${setup.configuration.nodes[0].stageKey}/${setup.configuration.nodes[0].nodeKey}` : ''; await loadNode() } catch (e) { message.value = e instanceof Error ? e.message : '配置来源应用失败' } finally { busy.value = false } }
function parseJsonObject(value: unknown, label: string) { try { const parsed = typeof value === 'string' ? JSON.parse(value || '{}') : (value ?? {}); if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error(`${label}必须是 JSON 对象`); return JSON.stringify(parsed) } catch (e) { throw new Error(`${label}格式无效：${e instanceof Error ? e.message : '请填写合法 JSON'}`) } }
async function saveNode() { if (!selectedNode.value || !selectedDraft.value) return; saving.value = true; try { const skills = (selectedDraft.value.skills ?? []).map((skill, index) => ({ ...skill, versionPolicy: 'LATEST_PUBLISHED' as const, fixedSkillVersionId: undefined, required: true, sortOrder: index })); selectedDraft.value.skills = skills; const outputSchemaJson = parseJsonObject(selectedDraft.value.outputSchemaJson, 'Output Schema'); const runtimeConfigJson = parseJsonObject(selectedDraft.value.runtimeConfigJson, 'Runtime Config'); await saveProjectAgentNodeDraft(projectKey, selectedNode.value.stageKey, selectedNode.value.nodeKey, { systemPrompt: selectedDraft.value.systemPrompt, modelCode: selectedDraft.value.modelCode, temperature: selectedDraft.value.temperature, maxIterationPerRun: selectedDraft.value.maxIterationPerRun, timeoutSeconds: selectedDraft.value.timeoutSeconds, outputSchemaJson, runtimeConfigJson, skills }); setup.clearValidation(); MessagePlugin.success('当前 Node 草稿已保存') } catch (e) { MessagePlugin.error(e instanceof Error ? e.message : '草稿保存失败') } finally { saving.value = false } }
async function saveContexts() { try { contexts.value = await saveProjectAgentContexts(projectKey, contexts.value); setup.clearValidation(); MessagePlugin.success('启动上下文已保存') } catch (e) { MessagePlugin.error(e instanceof Error ? e.message : '上下文保存失败') } }
async function revise() { try { setup.configuration = await reviseProjectAgentConfiguration(projectKey); setup.clearValidation(); MessagePlugin.success('已创建可编辑配置修订') } catch (e) { MessagePlugin.error(e instanceof Error ? e.message : '创建修订失败') } }
async function validate() { if (validating.value) return; validating.value = true; try { const result = await setup.validate(projectKey); if (result.valid) MessagePlugin.success('配置校验通过'); else MessagePlugin.warning(`配置校验未通过：${result.issues.length} 个问题`); } catch (e) { MessagePlugin.error(e instanceof Error ? e.message : '配置校验失败') } finally { validating.value = false } }
async function confirm() { try { await setup.confirm(projectKey) } catch (e) { message.value = e instanceof Error ? e.message : '配置确认失败' } }
async function start() { if (!initialRequest.value.trim() || !ready.value) return; try { const run = await startWorkflowRun(projectKey, { initialRequest: initialRequest.value.trim() }); await router.push({ name: 'project-workspace', params: { projectId: projectKey, runId: String(run.id) } }) } catch (e) { message.value = e instanceof Error ? e.message : 'Workflow 启动失败' } }
function remove(kind: 'platformWiki'|'feishu', item: ProjectAgentContext) { contexts.value[kind] = contexts.value[kind].filter(x => String(x.id) !== String(item.id)) }
async function searchContext() { try { if (contextTab.value === 'PLATFORM_WIKI') { const page = await getWikiDocuments({ keyword: wikiQuery.value.trim() || undefined, page: 0, size: 10 }); wikiResults.value = page.items.filter(x => x.platformVisible && x.active).map(x => ({ kind: 'PLATFORM_WIKI', id: x.id, title: x.title, revisionNo: x.revisionNo })) } else { const raw = await searchDocumentAgentFeishu(feishuQuery.value.trim()); const data = Array.isArray(raw) ? raw : (raw as any).result ?? raw; const items = (data as any).files ?? (data as any).items ?? (data as any).docs ?? []; feishuResults.value = items.filter((x: any) => x.readable !== false).map((x: any) => ({ kind: 'FEISHU', id: x.docId, title: x.title || x.docId, docType: x.docType, url: x.open_url })) } } catch (e) { message.value = e instanceof Error ? e.message : '上下文搜索失败' } }
function addContext(item: ProjectAgentContext) { const key = item.kind === 'PLATFORM_WIKI' ? 'platformWiki' : 'feishu'; if (contexts.value[key].some(x => String(x.id) === String(item.id)) || contexts.value[key].length >= 10) return; contexts.value[key] = [...contexts.value[key], item] }
</script>
<template>
  <main v-if="resolvingEntry" class="setup-workbench"><section class="panel muted">正在检查项目工作流…</section></main>
  <main v-else class="setup-workbench"><header class="hero"><div><p class="eyebrow">PROJECT AGENT SETUP</p><h1>项目 Agent 配置</h1><p class="muted">先复制为项目私有草稿，再按 Node 调整 Prompt、Skill 与启动资料。</p></div><div class="status-stack"><span class="status">{{ setup.configuration?.status || 'DRAFT' }}</span><button v-if="!draftMode" @click="revise">创建配置修订</button></div></header><p v-if="message || setup.error" class="notice">{{ message || setup.error }}</p>
    <section class="source panel"><div><span class="step">01</span><h2>配置来源</h2><p class="muted">来源应用后，每个 Node 都是当前项目独立副本。</p></div><div class="tabs"><button :class="{active:source==='SYSTEM_PRESET'}" @click="source='SYSTEM_PRESET'">系统推荐</button><button :class="{active:source==='PROJECT_COPY'}" @click="source='PROJECT_COPY'">历史项目</button><button :class="{active:source==='CUSTOM'}" @click="source='CUSTOM'">自定义</button></div><div v-if="source==='SYSTEM_PRESET'" class="inline"><select v-model="selectedPreset"><option v-for="p in presets" :key="String(p.versionId)" :value="p.versionId">{{ p.name }} v{{ p.versionNo }}</option></select><button @click="applySource">应用方案</button></div><div v-else-if="source==='PROJECT_COPY'" class="inline"><select v-model="sourceProjectKey"><option value="">选择历史项目</option><option v-for="p in setup.reusableProjects" :key="p.projectKey" :value="p.projectKey">{{ p.name }} · {{ p.status }}</option></select><button @click="applySource">复制为草稿</button></div><p v-else class="muted">选择下方 Node 后编辑项目私有 Agent。</p></section>
    <section class="editor panel"><div class="section-head"><div><span class="step">02</span><h2>Agent 团队</h2></div><span class="muted">{{ setup.configuration?.nodes.length || 0 }} Nodes</span></div><div class="editor-grid"><nav class="node-list"><section v-for="group in groupedNodes" :key="group.key" class="node-group"><h3>{{ group.label }}</h3><button v-for="n in group.nodes" :key="`${n.stageKey}/${n.nodeKey}`" :class="{selected:setup.selectedNodeKey===`${n.stageKey}/${n.nodeKey}`}" @click="setup.selectedNodeKey=`${n.stageKey}/${n.nodeKey}`; loadNode()"><strong>{{ n.nodeDisplayName || n.nodeName || n.nodeKey }}</strong><small>{{ n.nodeKey }} · {{ n.agentProfileCode }}</small></button></section></nav><article v-if="selectedDraft" class="inspector"><div class="section-head"><div><h3>{{ selectedDraft.nodeName || selectedDraft.nodeKey }}</h3><p class="muted">项目私有 Draft · 来源版本 {{ selectedDraft.sourceAgentProfileVersionId || '—' }}</p></div><button :disabled="saving || !draftMode" @click="saveNode">{{ saving ? '保存中…' : '保存此 Agent' }}</button></div><details class="locked-protocol"><summary>工作流执行协议 · 系统锁定</summary><pre>{{ selectedDraft.workflowProtocolPrompt || '该 Workflow Node 暂无协议文本' }}</pre><p class="hint">此协议负责 JSON 返回、resultCode、artifact、review 和人员介入闭环，运行时不可被角色指令覆盖。</p></details><label>Agent 角色与补充指令<textarea v-model="selectedDraft.systemPrompt" rows="9" :disabled="!draftMode" /></label><div class="form-grid"><label>Model<input v-model="selectedDraft.modelCode" :disabled="!draftMode" /></label><label>Temperature<input v-model.number="selectedDraft.temperature" type="number" step="0.1" :disabled="!draftMode" /></label><label>Max Iteration<input v-model.number="selectedDraft.maxIterationPerRun" type="number" :disabled="!draftMode" /></label><label>Timeout（秒）<input v-model.number="selectedDraft.timeoutSeconds" type="number" :disabled="!draftMode" /></label></div><details open><summary>Skills / Runtime 高级配置</summary><div class="skill-picker" data-testid="project-agent-skill-picker"><div class="skill-search"><input v-model="skillQuery" :disabled="!draftMode" placeholder="搜索平台 Skill" @keyup.enter="searchSkills" /><button type="button" :disabled="!draftMode || skillSearching" @click="searchSkills">{{ skillSearching ? '搜索中…' : '搜索' }}</button></div><p class="hint">Skill 将使用最新已发布版本。搜索结果可跨多次查询累积选择。</p><div v-if="skillResults.length" class="skill-results"><label v-for="skill in skillResults" :key="skill.skillKey" class="skill-option"><input type="checkbox" :checked="selectedSkill(skill.skillKey)" :disabled="!draftMode" @change="($event.target as HTMLInputElement).checked ? addSkill(skill) : removeSkill(skill.skillKey)" /><span><strong>{{ skill.displayName }}</strong><small>{{ skill.skillKey }} · {{ skill.developmentStage || '未标记' }}</small></span></label></div><p v-else class="empty compact">输入关键字搜索平台 Skill</p><div class="selected-skills"><span v-for="skill in selectedDraft.skills || []" :key="skill.skillKey" class="skill-chip">{{ skill.name || skill.skillKey }}<button type="button" :disabled="!draftMode" :aria-label="`移除 ${skill.name || skill.skillKey}`" @click="removeSkill(skill.skillKey)">×</button></span><p v-if="!(selectedDraft.skills || []).length" class="muted">尚未选择 Skill</p></div><label>Runtime Config JSON<textarea v-model="runtimeConfigText" rows="5" :disabled="!draftMode" /></label></div></details></article><p v-else class="empty">选择一个 Node 开始编辑</p></div></section>
    <section class="context panel"><div class="section-head"><div><span class="step">03</span><h2>启动上下文</h2><p class="muted">整个 Run 共享；平台 Wiki 启动时固定版本，飞书固定文档身份。</p></div><button :disabled="!draftMode" @click="saveContexts">保存上下文</button></div><div class="context-tabs"><button :class="{active:contextTab==='PLATFORM_WIKI'}" @click="contextTab='PLATFORM_WIKI'">平台 Wiki <b>{{ contexts.platformWiki.length }}/10</b></button><button :class="{active:contextTab==='FEISHU'}" @click="contextTab='FEISHU'">飞书 <b>{{ contexts.feishu.length }}/10</b></button></div><div class="context-search"><input v-if="contextTab==='PLATFORM_WIKI'" v-model="wikiQuery" placeholder="搜索平台 Wiki" @keyup.enter="searchContext" /><input v-else v-model="feishuQuery" placeholder="搜索或粘贴飞书文档" @keyup.enter="searchContext" /><button @click="searchContext">搜索</button></div><div class="results"><button v-for="item in contextTab==='PLATFORM_WIKI'?wikiResults:feishuResults" :key="`${item.kind}-${item.id}`" @click="addContext(item)"><span>{{ item.title }}</span><small>{{ item.revisionNo ? `v${item.revisionNo}` : item.docType }}</small></button></div><div class="selected"><span v-for="item in contexts[contextTab==='PLATFORM_WIKI'?'platformWiki':'feishu']" :key="String(item.id)" class="tag">{{ item.title }} <button @click="remove(contextTab==='PLATFORM_WIKI'?'platformWiki':'feishu',item)">×</button></span><p v-if="!contexts[contextTab==='PLATFORM_WIKI'?'platformWiki':'feishu'].length" class="muted">尚未选择资料</p></div></section>
    <section class="footer panel"><div><span class="step">04</span><h2>校验并启动</h2><p class="muted">确认后项目 Agent 草稿冻结；启动时生成上下文快照。</p></div><div class="actions"><button :disabled="validating" @click="validate">{{ validating ? '校验中…' : '校验配置' }}</button><button v-if="setup.configuration?.status==='READY'" class="primary" :disabled="!initialRequest.trim()" @click="start">启动 Workflow</button><button v-else class="primary" @click="confirm">确认配置</button></div><div v-if="setup.validation" class="validation-result" :class="{valid: setup.validation.valid, invalid: !setup.validation.valid}" data-testid="config-validation-result"><strong>{{ setup.validation.valid ? '配置校验通过' : '配置校验未通过' }}</strong><div class="checks"><span v-for="check in setup.validation.checks || []" :key="check.label" :class="{passed: check.passed}">{{ check.passed ? '✓' : '!' }} {{ check.label }}</span></div><ul v-if="setup.validation.issues.length"><li v-for="issue in setup.validation.issues" :key="issue">{{ issue }}</li></ul><p v-else class="muted">所有配置检查均已通过。</p></div><textarea v-if="setup.configuration?.status==='READY'" v-model="initialRequest" data-testid="initial-request" rows="3" placeholder="输入本次研发需求" /></section>
  </main>
</template>
<style scoped>
.setup-workbench{max-width:1240px;margin:auto;padding-bottom:70px}.hero,.section-head,.inline,.actions,.context-search{display:flex;align-items:center;justify-content:space-between;gap:14px}.hero{align-items:flex-start}.eyebrow,.step{color:var(--accent-500);font-size:11px;letter-spacing:.14em}.muted{color:var(--text-2)}.hint{margin:0;color:var(--text-3);font-size:12px}.status-stack{display:flex;gap:8px;align-items:center}.status,.tag{padding:7px 10px;border-radius:999px;background:var(--surface-2)}.panel{margin:16px 0;padding:22px;border:1px solid var(--border-1);border-radius:14px;background:var(--surface-1)}h2,h3{margin:4px 0}.tabs,.context-tabs{display:flex;gap:8px;margin:14px 0}.tabs button,.context-tabs button,.panel button{padding:9px 13px;border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2);color:var(--text-1)}.tabs .active,.context-tabs .active,.primary{color:#fff;background:var(--accent-600);border-color:var(--accent-600)}.inline{justify-content:flex-start}.inline select,.context-search input,.panel input,.panel textarea{padding:10px;border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2);color:var(--text-1);font:inherit}.editor-grid{display:grid;grid-template-columns:280px 1fr;gap:18px}.node-list{display:grid;align-content:start;gap:8px}.node-list button{display:grid;text-align:left;gap:5px}.node-list button.selected{border-color:var(--accent-500);box-shadow:inset 3px 0 var(--accent-500)}.node-list small{color:var(--text-2)}.inspector{display:grid;gap:14px}.inspector label{display:grid;gap:6px;color:var(--text-2)}.locked-protocol{border:1px solid rgb(148 163 184 / 35%);border-radius:10px;padding:10px 12px;background:var(--bg-2)}.locked-protocol summary{cursor:pointer;color:var(--text-2);font-weight:650}.locked-protocol pre{white-space:pre-wrap;max-height:260px;overflow:auto;margin:12px 0;padding:12px;border-radius:8px;background:var(--surface-2);color:var(--text-2);font:12px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.skill-picker{display:grid;gap:10px;padding-top:8px}.skill-search{display:flex;gap:8px}.skill-search input{flex:1}.skill-results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:260px;overflow:auto}.skill-option{display:flex!important;grid-template-columns:none!important;align-items:flex-start;gap:9px;padding:10px;border:1px solid var(--border-1);border-radius:8px;background:var(--surface-2);cursor:pointer}.skill-option:has(input:checked){border-color:var(--accent-500);background:var(--accent-soft)}.skill-option span{display:grid;gap:3px}.skill-option small{color:var(--text-2)}.selected-skills{display:flex;flex-wrap:wrap;gap:7px;min-height:42px;align-items:center;padding:8px;border:1px dashed var(--border-1);border-radius:8px}.skill-chip{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border-radius:999px;background:var(--surface-2);color:var(--text-1)}.skill-chip button{border:0!important;padding:0!important;background:transparent!important}.compact{padding:12px;margin:0}.json-preview{max-height:180px;overflow:auto;white-space:pre-wrap;color:var(--text-2)}.context-search{justify-content:flex-start}.context-search input{flex:1}.selected,.results{display:flex;flex-wrap:wrap;gap:7px;min-height:44px;align-items:center}.results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));margin-top:10px}.results button{display:flex;justify-content:space-between;text-align:left}.results small{color:var(--text-2)}.tag{display:inline-flex;gap:6px}.tag button{border:0;padding:0;background:transparent}.empty{padding:40px;color:var(--text-2)}.validation-result{display:grid;gap:10px;margin-top:16px;padding:14px 16px;border:1px solid var(--border-1);border-radius:10px}.validation-result.valid{border-color:rgb(34 197 94 / 45%);background:rgb(34 197 94 / 8%)}.validation-result.invalid{border-color:rgb(248 113 113 / 45%);background:rgb(248 113 113 / 8%)}.checks{display:flex;flex-wrap:wrap;gap:8px}.checks span{padding:5px 8px;border-radius:999px;background:var(--surface-2);color:var(--error)}.checks span.passed{color:var(--success)}.validation-result ul{margin:0;padding-left:20px;color:var(--error)}.footer textarea{width:100%;margin-top:14px;box-sizing:border-box}@media(max-width:760px){.hero,.section-head{display:block}.editor-grid{grid-template-columns:1fr}.form-grid,.results,.skill-results{grid-template-columns:1fr}.status-stack{margin-top:12px}}
.node-list { gap: 14px; }
.node-group { display: grid; gap: 7px; }
.node-group h3 { margin: 0; padding: 0 4px; color: var(--text-2); font-size: 12px; font-weight: 650; }
</style>
